 MetaRuntime host (Zig)  
Az alábbi app_V24.zig moduláris host mikrokernel, amely a GPUAdaptert Futhark C‑interfésszel és opcionális SYCL úttal hívja, a DistAdapterrel Chapel folyamatot vezérel és a SymbAdapteren át HTTP‑n beszél a Rosette szolgáltatással; mindez a V23.5 mintát követi, de PFR‑től független, saját adapterekkel [1][8][9][4][6][10].  

zig
// FILE: meta_runtime/app_V24.zig
const std = @import("std");
const json = std.json;

const GPUAdapter = @import("gpu/adapter.zig");
const DistAdapter = @import("dist/adapter.zig");
const SymbAdapter = @import("symb/adapter.zig");

pub const V24Config = struct {
    enable_gpu_adapter: bool = true,
    enable_sycl: bool = true,
    enable_jit: bool = true,
    enable_rosette: bool = true,
    enable_kcell: bool = true,
    enable_chapel_runner: bool = true,
    enable_pony_telemetry: bool = true,

    futhark_lib_path: []const u8,
    chapel_runner_path: []const u8,
    pony_monitor_path: []const u8,
    rosette_service_url: []const u8,
};

pub fn readConfig(alloc: std.mem.Allocator, path: []const u8) !V24Config {
    var file = try std.fs.cwd().openFile(path, .{ .read = true });
    defer file.close();
    var buf = try file.readToEndAlloc(alloc, 1024 * 1024);
    defer alloc.free(buf);

    var parsed = try json.parseFromSlice(std.json.Value, alloc, buf, .{});
    defer parsed.deinit();

    const root = parsed.value;
    const system = root.object.get("system").?;
    const features = system.object.get("features").?;
    const paths = root.object.get("paths").?;

    const cfg = V24Config{
        .enable_gpu_adapter = features.object.get("enable_gpu_adapter").?.bool,
        .enable_sycl = features.object.get("enable_sycl").?.bool,
        .enable_jit = features.object.get("enable_jit").?.bool,
        .enable_rosette = features.object.get("enable_rosette").?.bool,
        .enable_kcell = features.object.get("enable_kcell").?.bool,
        .enable_chapel_runner = features.object.get("enable_chapel_runner").?.bool,
        .enable_pony_telemetry = features.object.get("enable_pony_telemetry").?.bool,
        .futhark_lib_path = paths.object.get("futhark_lib").?.string,
        .chapel_runner_path = paths.object.get("chapel_runner").?.string,
        .pony_monitor_path = paths.object.get("pony_monitor").?.string,
        .rosette_service_url = paths.object.get("rosette_service_url").?.string,
    };
    return cfg;
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const alloc = gpa.allocator();

    const cfg = try readConfig(alloc, "config/system_V24.json");

    var gpu: ?GPUAdapter = null;
    if (cfg.enable_gpu_adapter) {
        gpu = try GPUAdapter.init(alloc, cfg.futhark_lib_path, cfg.enable_sycl, cfg.enable_jit);
        defer if (gpu) |*g| g.deinit();
    }

    var dist: ?DistAdapter = null;
    if (cfg.enable_chapel_runner) {
        dist = try DistAdapter.init(alloc, cfg.chapel_runner_path);
        defer if (dist) |*d| d.deinit();
    }

    var symb: ?SymbAdapter = null;
    if (cfg.enable_rosette) {
        symb = try SymbAdapter.init(alloc, cfg.rosette_service_url);
        defer if (symb) |*s| s.deinit();
    }

    if (cfg.enable_pony_telemetry) {
        // Egyszerű monitor folyamat indítás
        var child = std.ChildProcess.init(&.{ cfg.pony_monitor_path }, alloc);
        defer child.deinit();
        _ = child.spawn() catch {};
    }

    // GPU szakasz (matvec példa)
    if (gpu) |*ga| {
        var A: [16]f32 = .{0} ** 16;
        var x: [4]f32 = .{1, 2, 3, 4};
        // Töltsünk fel egy 4x4 mátrixot
        for (A, 0..) |*v, i| v.* = @as(f32, @floatFromInt((i % 5) + 1));
        var y: [4]f32 = .{0} ** 4;
        try ga.matvec(&A, 4, 4, &x, &y);
        std.debug.print("[GPU] y = {d:.3} {d:.3} {d:.3} {d:.3}\n", .{ y, y[1], y[2], y[3] });
    }

    // Disztribuált Chapel futtatás
    if (dist) |*da| {
        const report = try da.runShard(0, 4);
        defer alloc.free(report);
        std.debug.print("[DIST] report: {s}\n", .{report});
    }

    // Rosette ellenőrzés
    if (symb) |*sa| {
        const ok = try sa.verifyPrePost("{\"pre\":\"(> x 0)\",\"post\":\"(>= y x)\",\"prog\":\"(define (f x) (+ x 1))\",\"check\":\"(assert (=> pre (post)))\"}");
        std.debug.print("[ROSETTE] verify: {s}\n", .{if (ok) "ok" else "fail"});
    }
}


