// FILE: meta_runtime/gpu/adapter.zig
const std = @import("std");

pub const GPUAdapter = struct {
    alloc: std.mem.Allocator,
    futhark: FutharkIface,
    enable_sycl: bool,
    enable_jit: bool,

    pub fn init(alloc: std.mem.Allocator, lib_path: []const u8, enable_sycl: bool, enable_jit: bool) !GPUAdapter {
        var iface = try FutharkIface.load(alloc, lib_path);
        return .{
            .alloc = alloc,
            .futhark = iface,
            .enable_sycl = enable_sycl,
            .enable_jit = enable_jit,
        };
    }

    pub fn deinit(self: *GPUAdapter) void {
        self.futhark.unload(self.alloc);
    }

    pub fn matvec(self: *GPUAdapter, A: []const f32, rows: usize, cols: usize, x: []const f32, y_out: []f32) !void {
        if (rows * cols != A.len or cols != x.len or rows != y_out.len) return error.InvalidDims;
        // Hívjuk a Futhark C-hídon át generált függvényt (libv24_kernels.so)
        try self.futhark.matvec(A, rows, cols, x, y_out);
        // Opcionális: SYCL fallback itt bővíthető (DPC++ host-kód) – a hordozhatóságot a toolchain biztosítja
    }
};

const FutharkIface = struct {
    handle: std.DynLib,
    matvec_sym: ?*const fn ([*]const f32, usize, usize, [*]const f32, [*]f32) callconv(.C) void,

    pub fn load(alloc: std.mem.Allocator, lib_path: []const u8) !FutharkIface {
        var dl = try std.DynLib.open(lib_path);
        const sym = dl.lookup(*const fn([*]const f32, usize, usize, [*]const f32, [*]f32) callconv(.C) void, "v24_matvec") orelse return error.SymbolNotFound;
        return .{ .handle = dl, .matvec_sym = sym };
    }

    pub fn unload(self: *FutharkIface, _: std.mem.Allocator) void {
        self.handle.close();
    }

    pub fn matvec(self: *FutharkIface, A: []const f32, rows: usize, cols: usize, x: []const f32, y_out: []f32) !void {
        if (self.matvec_sym) |f| {
            f(A.ptr, rows, cols, x.ptr, y_out.ptr);
            return;
        }
        return error.SymbolNotFound;
    }
};

pub fn init(alloc: std.mem.Allocator, lib_path: []const u8, enable_sycl: bool, enable_jit: bool) !GPUAdapter {
    return GPUAdapter.init(alloc, lib_path, enable_sycl, enable_jit);
}


zig
// FILE: meta_runtime/dist/adapter.zig
const std = @import("std");

pub const DistAdapter = struct {
    alloc: std.mem.Allocator,
    runner_path: []const u8,

    pub fn init(alloc: std.mem.Allocator, runner_path: []const u8) !DistAdapter {
        return .{ .alloc = alloc, .runner_path = try alloc.dupe(u8, runner_path) };
    }

    pub fn deinit(self: *DistAdapter) void {
        self.alloc.free(self.runner_path);
    }

    pub fn runShard(self: *DistAdapter, shard_id: usize, shards: usize) ![]u8 {
        var args = std.ArrayList([]const u8).init(self.alloc);
        defer args.deinit();

        try args.append(self.runner_path);
        try args.append("--shard");
        try args.append(try std.fmt.allocPrint(self.alloc, "{d}", .{shard_id}));
        try args.append("--shards");
        try args.append(try std.fmt.allocPrint(self.alloc, "{d}", .{shards}));

        var child = std.ChildProcess.init(args.items, self.alloc);
        defer child.deinit();
        child.stdout_behavior = .Pipe;
        child.stderr_behavior = .Pipe;

        try child.spawn();

        var out = std.ArrayList(u8).init(self.alloc);
        defer out.deinit();

        var reader = child.stdout.?;
        var buf: u8 = undefined;
        while (true) {
            const n = try reader.read(&buf);
            if (n == 0) break;
            try out.appendSlice(buf[0..n]);
        }
        _ = try child.wait();
        return out.toOwnedSlice();
    }
};

pub fn init(alloc: std.mem.Allocator, runner_path: []const u8) !DistAdapter {
    return DistAdapter.init(alloc, runner_path);
}


zig
// FILE: meta_runtime/symb/adapter.zig
const std = @import("std");

pub const SymbAdapter = struct {
    alloc: std.mem.Allocator,
    base_url: []const u8,

    pub fn init(alloc: std.mem.Allocator, base_url: []const u8) !SymbAdapter {
        return .{ .alloc = alloc, .base_url = try alloc.dupe(u8, base_url) };
    }

    pub fn deinit(self: *SymbAdapter) void {
        self.alloc.free(self.base_url);
    }

    pub fn verifyPrePost(self: *SymbAdapter, payload_json: []const u8) !bool {
        var client = std.http.Client{ .allocator = self.alloc };
        defer client.deinit();

        var req = try client.request(.POST, try std.Uri.parse(self.base_url ++ "/verify"), .{}, .{});
        defer req.deinit();

        try req.send(payload_json);
        try req.finish();
        const res = try req.reader().readAllAlloc(self.alloc, 64 * 1024);
        defer self.alloc.free(res);

        return std.mem.indexOf(u8, res, "ok") != null;
    }
};

pub fn init(alloc: std.mem.Allocator, base_url: []const u8) !SymbAdapter {
    return SymbAdapter.init(alloc, base_url);
}


 Futhark GPU kernel (C hídhoz)  
A Futhark “v24_matvec” kernel exportál C ABI‑n át Zigből hívható szignatúrával, amelyet a Futhark hivatalos dokumentáció szerinti C kódgenerátorával építünk és dinamikus könyvtárba csomagolunk [8][9][12][13].  

futhark
-- FILE: futhark/kernels_v24.fut
-- Egyszerű 4x4 matvec minta, demonstrációs célra paraméterezhetővé téve
entry v24_matvec (rows: i64) (cols: i64) (A: [rows][cols]f32) (x: [cols]f32): [rows]f32 =
  map (\row -> f32.sum (map2 (*) row x)) A


C wrapper az ABI‑hez (nevezett export, a Futhark C‑backend fordítás után .so‑ba linkelve) [8][9].  

c
// FILE: futhark/capi_v24.c
#include <stdint.h>
#include <stdlib.h>

// A Futhark fordító által generált header (build során):
#include "kernels_v24.h"

// Egyszerű export a Zighez: lapos tömböket vesz át
__attribute__((visibility("default")))
void v24_matvec(const float* A_flat, size_t rows, size_t cols, const float* x, float* y_out) {
  struct futhark_context_config* cfg = futhark_context_config_new();
  struct futhark_context* ctx = futhark_context_new(cfg);

  // Feltöltjük a Futhark tömböket
  struct futhark_f32_2d* A = futhark_new_f32_2d(ctx, A_flat, rows, cols);
  struct futhark_f32_1d* X = futhark_new_f32_1d(ctx, x, cols);

  struct futhark_f32_1d* Y = NULL;
  // A Futhark generált belépési pont: v24_matvec
  futhark_entry_v24_matvec(ctx, &Y, rows, cols, A, X);

  // Kiolvasás
  futhark_values_f32_1d(ctx, Y, y_out);

  // Takarítás
  futhark_free_f32_2d(ctx, A);
  futhark_free_f32_1d(ctx, X);
  futhark_free_f32_1d(ctx, Y);
  futhark_context_free(ctx);
  futhark_context_config_free(cfg);
}


 Chapel futtató (elosztott)  
A runner szegmensekre bont, futtat és JSON telemetriát ír a host számára, a Chapel dokumentáció szerinti fordítási és futtatási modellel [1][10][14].  

chapel
// FILE: chapel/runner_V24.chpl
use Time, IO;

config const shard: int = 0;
config const shards: int = 1;

proc computeSegment(seg:int, total:int): real {
  var acc: real = 0.0;
  for i in seg..#(1000000/total) {
    acc += (i:real) * 0.000001;
  }
  return acc;
}

proc main() {
  var t = new Timer();
  t.start();
  const val = computeSegment(shard, shards);
  t.stop();

  var w = openfd(stdout).writer();
  w.writef("{\"shard\":%i,\"shards\":%i,\"value\":%.6dr,\"elapsed_ms\":%.2dr}\n",
           shard, shards, val, t.elapsed()*1000.0);
}


