#lang racket
;; FILE: rosette_service/server.rkt
(require racket/json
         web-server/servlet
         web-server/servlet-env
         rosette)

(define (verify-handler req)
  (define in (request-post-data/raw req))
  (define payload (bytes->jsexpr in))
  (define pre-expr (hash-ref payload 'pre))
  (define post-expr (hash-ref payload 'post))
  (define prog (hash-ref payload 'prog))
  (define chk (hash-ref payload 'check))

  (define-symbolic x integer?)
  (define-symbolic y integer?)

  (define verified?
    (with-handlers ([exn:fail? (lambda (e) #f)])
      (and (boolean? (solve (assert #t))) ; csatorna ellenőrzés
           #t)))

  (response/output
   (lambda (out)
     (display (jsexpr->string (hash 'status (if verified? "ok" "fail"))) out))))

(define (start req)
  (define path (url-path (request-uri req)))
  (cond
    [(equal? path (list (make-path/param "verify" '()))) (verify-handler req)]
    [else (response/output (lambda (out) (display "{\"status\":\"unknown\"}" out)))]))

