const std = @import("std");
const GPU = @import("../meta_runtime/gpu/adapter.zig");
const Dist = @import("../meta_runtime/dist/adapter.zig");

test "V24 GPUAdapter init" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const a = gpa.allocator();
    var gpu = try GPU.init(a, "build/futhark/libv24_kernels.so", true, true);
    defer gpu.deinit();
}

test "V24 DistAdapter shard run" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const a = gpa.allocator();
    var da = try Dist.init(a, "build/chapel/runner_V24");
    defer da.deinit();
    const out = try da.runShard(0, 2);
    defer a.free(out);
    try std.testing.expect(std.mem.indexOf(u8, out, "\"shard\":0") != null);
}


